def gen(rng):
    def relabel(par):
        n = len(par)
        rest = list(range(1, n))
        rng.shuffle(rest)
        perm = [0] + rest
        new = [-1] * n
        for i in range(1, n):
            new[perm[i]] = perm[par[i]]
        return new

    def make(n, kind):
        par = [-1] * n
        for i in range(1, n):
            if kind == 'chain':
                par[i] = i - 1
            elif kind == 'star':
                par[i] = 0
            elif kind == 'binary':
                par[i] = (i - 1) // 2
            elif kind == 'deep':
                par[i] = rng.randint(max(0, i - 3), i - 1)
            else:
                par[i] = rng.randint(0, i - 1)
        return relabel(par)

    def depth_of(par):
        n = len(par)
        d = [-1] * n
        for s in range(n):
            if d[s] >= 0:
                continue
            path = []
            v = s
            while v != -1 and d[v] < 0:
                path.append(v)
                v = par[v]
            base = -1 if v == -1 else d[v]
            for u in reversed(path):
                base += 1
                d[u] = base
        return d

    def fmt(par, queries):
        return (str(len(par)) + '\n' + ' '.join(map(str, par)) + '\n' + str(len(queries)) + '\n'
                + '\n'.join('%d %d' % qk for qk in queries))

    def queries_for(par, q):
        n = len(par)
        d = depth_of(par)
        res = []
        for _ in range(q):
            v = rng.randrange(n)
            t = rng.random()
            if t < 0.25:
                k = rng.randint(1, min(n, 3))
            elif t < 0.5:
                k = max(1, d[v])
            elif t < 0.65:
                k = min(n, d[v] + 1)
            elif t < 0.85:
                k = rng.randint(1, max(1, d[v]))
            else:
                k = rng.randint(1, n)
            res.append((v, k))
        return res

    tests = [fmt([-1], [(0, 1)]), fmt([-1, 0], [(1, 1), (1, 2), (0, 1), (0, 2)])]
    for n in (3, 5, 8, 12, 20, 30):
        for kind in ('random', 'chain', 'deep', 'binary', 'star'):
            par = make(n, kind)
            tests.append(fmt(par, queries_for(par, 15)))
    N = 100000
    Q = 100000
    for kind in ('chain', 'deep', 'random', 'binary'):
        par = make(N, kind)
        tests.append(fmt(par, queries_for(par, Q)))
    par = make(N, 'chain')
    tests.append(fmt(par, [(rng.randrange(N), N) for _ in range(Q)]))
    return tests

